section('Control Center on D1: central numbers from several apps');
{
  const CEN = makeD1(), coachLike = { id: 'coach', url: 'https://axm-02.pages.dev', button: 'Interview Coach', defaults: { appName: 'Interview Coach' } };
  const now = new Date().toISOString(), lastM = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth() - 1, 10)).toISOString();
  const seed = async (mod, sql) => { const A = await makeSim(mod, { central: CEN }); sql.forEach(([q, ...a]) => A.env.DB._db.prepare(q).run(...a)); await A.cron('daily'); await A.cron('hourly'); return A; };
  const pay = 'INSERT INTO Payments (order_id,user_id,app,plan,amount,currency,method,status,created_at,paid_at) VALUES (?,?,?,?,?,?,?,?,?,?)';
  const user = 'INSERT INTO Users (user_id,app,first_name,created_at,last_seen) VALUES (?,?,?,?,?)';
  const D = await seed(debt, [[pay, 'P0', '90', 'debt', 'pro_m', '2.00', 'USD', 'evc', 'paid', now, now], [pay, 'P1', '91', 'debt', 'pro_m', 150, 'XTR', 'stars', 'paid', now, now], [pay, 'PR', '98', 'debt', 'pro_m', '$2.00', 'USD', 'evc', 'review', now, null],
    ['INSERT INTO Subscriptions (user_id,app,plan,status,start_date,expiry_date) VALUES (?,?,?,?,?,?)', '90', 'debt', 'pro_m', 'active', now, new Date(Date.now() + 20 * 864e5).toISOString()],
    [user, '70', 'debt', 'Secret Customer', now, now], [user, '71', 'debt', 'U', now, now]]);
  await seed(coachLike, [[pay, 'P2', '92', 'coach', 's10', '7.0012', 'USDT', 'usdt_trc20', 'paid', now, now], [pay, 'P3', '93', 'coach', 's1', 75, 'XTR', 'stars', 'paid', lastM, lastM], [user, '72', 'coach', 'U', now, now]]);
  await seed(rsvpMod, [[pay, 'P4', '94', 'rsvp', 'event1', '5.00', 'USD', 'zaad', 'paid', now, now], [user, '73', 'rsvp', 'U', now, now]]);
  const C = await makeSim(controlMod, { central: CEN });
  CEN._db.prepare('UPDATE Apps SET hb_5min = ? WHERE app = ?').run(new Date(Date.now() - 3 * 36e5).toISOString(), 'coach');
  CEN._db.prepare("INSERT INTO Tickets (ticket_id,app,user_id,user_name,type,status,priority,created_at,updated_at) VALUES ('T1','debt','70','Amina','payment','open','high',?,?)").run(now, now);
  CEN._db.prepare("INSERT INTO TicketMsgs (ticket_id,\"from\",author_id,text,created_at) VALUES ('T1','user','70','I paid by EVC but no access',?)").run(now);
  CEN._db.prepare("INSERT INTO Tickets (ticket_id,app,user_id,type,status,priority,created_at,updated_at) VALUES ('T2','coach','72','suggestion','open','normal',?,?)").run(now, now);
  ok('central holds numbers only (no names or phones)', !JSON.stringify(CEN._db.prepare('SELECT * FROM Stats').all()).match(/Secret|Amina/));
  r = await C.call(ADMIN, 'ccOverview', {}); const db = r.byApp.find((a) => a.app === 'debt');
  ok('overview: per-app income this month (stars converted)', r.ok && Math.abs(db.mtd - (2 + 150 * 0.013)) < 0.01 && r.totals.ordersMtd === 4, { db, t: r.totals });
  ok('overview: last month, subscribers, open tickets', r.byApp.find((a) => a.app === 'coach').lastMonth > 0 && db.subs === 1 && r.totals.openTickets === 2, r.byApp);
  ok('overview: projection and charts', r.totals.projection >= r.totals.mtd && r.months.length === 12 && r.daily.length >= 28);
  ok('overview: apps appear by themselves', ['debt', 'coach', 'rsvp'].every((a) => r.apps.some((x) => x.app === a)));
  r = await C.call(ADMIN, 'ccOverview', { only: 'coach' }); ok('overview filter by app', r.byApp.length === 1 && r.byApp[0].app === 'coach', r.byApp);
  r = await C.call(ADMIN, 'ccHealth'); const ch = r.apps.find((a) => a.app === 'coach'), dh = r.apps.find((a) => a.app === 'debt');
  ok('health: stopped jobs flagged', ch.status === 'bad' && /stopped/.test(ch.issues.join()), ch);
  ok('health: payment review flagged', dh.review === 1 && dh.issues.some((x) => /approval/.test(x)), dh);
  ok('health: speed not judged on a few requests', dh.speedJudged === false && !dh.issues.some((x) => /slow/i.test(x)));
  const CA = { id: 6161, first_name: 'CoachAdmin' };
  CEN._db.prepare("INSERT INTO Admins (user_id,role,apps,perms,active) VALUES ('6161','app_admin','coach','support,reports',1)").run();
  r = await C.call(CA, 'ccOverview', {}); ok('app admin sees only their app', r.byApp.every((a) => a.app === 'coach') && r.apps.every((a) => a.app === 'coach'), r.byApp.map((a) => a.app));
  ok('app admin inbox scoped', (await C.call(CA, 'ccTickets', {})).items.every((x) => x.app === 'coach'));
  ok('app admin cannot open other app ticket', (await C.call(CA, 'ccTicket', { id: 'T1' })).error === 'forbidden');
  ok('app admin cannot manage admins', (await C.call(CA, 'ccAdmins')).error === 'forbidden');
  r = await C.call(ADMIN, 'ccTickets', {}); ok('inbox: high priority first, with preview', r.items[0].id === 'T1' && /EVC/.test(r.items[0].preview), r.items);
  ok('reply goes into the Debt Book queue', (await C.call(ADMIN, 'ccReply', { id: 'T1', text: 'Approved — you have access now.' })).ok && CEN._db.prepare("SELECT * FROM Outbox WHERE app='debt' AND chat_id='70'").all().some((m) => /Approved/.test(m.text)));
  ok('ticket marked answered', (await C.call(ADMIN, 'ccTicket', { id: 'T1' })).ticket.status === 'answered');
  r = await D.cron('5min'); ok('Debt Book sends its own queue (support reply)', r.sent >= 1 && CEN._db.prepare("SELECT status FROM Outbox WHERE app='debt' AND chat_id='70'").get().status === 'sent', r);
  ok('super adds an app admin', (await C.call(ADMIN, 'ccAdminSave', { user_id: '7777', name: 'Hodan', role: 'app_admin', apps: 'debt', perms: 'support,payments' })).ok && (await C.call(ADMIN, 'ccAdmins')).items.some((x) => x.user_id === '7777' && x.perms === 'support,payments'));
  ok('new admin told through the Control Center bot', CEN._db.prepare("SELECT * FROM Outbox WHERE app='control' AND chat_id='7777'").all().length === 1);
  ok('admin without scope refused', (await C.call(ADMIN, 'ccAdminSave', { user_id: '7778', role: 'app_admin', apps: '', perms: '' })).error === 'scope');
  ok('remove admin', (await C.call(ADMIN, 'ccAdminRemove', { user_id: '7777' })).ok && (await C.call(ADMIN, 'ccAdmins')).items.find((x) => x.user_id === '7777').active === false);
  ok('AI not configured -> clear error', (await C.call(ADMIN, 'ccAsk', { q: 'How is income?' })).error === 'ai_not_configured');
  await C.eng._setSecret(C.E, 'DEEPSEEK_KEY', 'k'); let sentAI = null;
  C.reply = (url, o) => { if (/deepseek/.test(url)) { sentAI = JSON.parse(o.body); return { choices: [{ message: { content: 'Coach background jobs stopped 3 h ago.' } }] }; } return null; };
  r = await C.call(ADMIN, 'ccAsk', { diagnose: true }); ok('AI diagnosis via DeepSeek with live snapshot', r.ok && /stopped/.test(r.answer) && /LIVE SNAPSHOT/.test(sentAI.messages[0].content) && /coach/.test(sentAI.messages[0].content) && /READ-ONLY/.test(sentAI.messages[0].content), r);
  ok('assistant briefed not to over-alarm', /Do NOT recommend Maintenance mode for slowness/.test(sentAI.messages[0].content) && /speedJudged/.test(sentAI.messages[0].content));
  ok('AI draft reply for a ticket', (await C.call(ADMIN, 'ccDraft', { id: 'T2' })).ok);
  ok('non-admin blocked from control data', (await C.call(V, 'ccOverview', {})).error === 'forbidden');
  C.reply = null;
}

section('Interview Coach and Document Translator on D1 (AI)');
{
  const gem = (obj) => ({ candidates: [{ content: { parts: [{ text: JSON.stringify(obj) }] } }], usageMetadata: { totalTokenCount: 100 } });
  S = await makeSim(coachMod); await S.setSettings({ testMode: false }); await S.eng._setSecret(S.E, 'GEMINI_KEY', 'k');
  S.reply = (url) => (/generativelanguage/.test(url) ? gem({ transcript: 'I want to study', overall: 72, scores: { content: 70, structure: 75, clarity: 80, confidence: 60 }, strengths: ['a'], improvements: ['b'], better_answer: 'c' }) : null);
  r = await S.call(U, 'coScore', { category: 'visa', question: 'Why?', audio: 'A'.repeat(2000), seconds: 30, lang: 'so' }); ok('scored + charged', r.ok && r.result.overall === 72 && r.access.freeLeft === 1, r);
  ok('Gemini called with the WAV', S.fetches.some((f) => /generativelanguage/.test(f.url) && /audio\/wav/.test(String(f.o.body))));
  ok('history saved', (await S.call(U, 'coHistory')).items.length === 1);
  ok('progress report locked on a free account', (await S.call(U, 'coReport')).allowed === false);
  await S.setSettings({ testMode: true }); r = await S.call(U, 'coReport'); ok('progress report data', r.allowed && r.sessions.length === 1 && r.sessions[0].scores.clarity === 80, r);
  let calls = 0; S.reply = (url) => { if (!/generativelanguage/.test(url)) return null; calls++; return calls === 1 ? { __code: 503, error: { message: 'high demand' } } : gem({ transcript: 't', overall: 50, scores: {} }); };
  r = await S.call(U, 'coScore', { category: 'job', question: 'Q', audio: 'A'.repeat(2000), seconds: 20 });
  ok('backup model used when Google is busy (503)', r.ok && r.result.overall === 50 && S.fetches.filter((f) => /flash-lite/.test(f.url)).length >= 1, r);
  ok('AI prompt has the injection guard', S.fetches.some((f) => /untrusted user/.test(String(f.o && f.o.body))));
  calls = 5; await S.setSettings({ x_aiUserDaily: 1, testMode: true }); await S.call(V, 'coScore', { category: 'job', question: 'Q', audio: 'A'.repeat(2000) }); r = await S.call(V, 'coScore', { category: 'job', question: 'Q', audio: 'A'.repeat(2000) });
  ok('AI per-user daily cap', r.error === 'ai_user_cap', r); await S.setSettings({ x_aiUserDaily: 30, testMode: false });
  S.reply = (url) => (/generativelanguage/.test(url) ? { candidates: [{ content: { parts: [{ text: 'not json' }] } }] } : null);
  r = await S.call(U, 'coScore', { category: 'visa', question: 'Why?', audio: 'A'.repeat(2000) }); ok('AI failure not charged', r.ok === false && (await S.call(U, 'init')).access.freeLeft === 1, r);
  S.reply = (url) => { if (/\/models\?/.test(url)) return { models: [{ name: 'models/gemini-3.6-flash', supportedGenerationMethods: ['generateContent'] }] }; if (/flash-latest|flash-lite-latest/.test(url)) return { __code: 404, error: { message: 'not found' } }; return /generativelanguage/.test(url) ? gem({ transcript: 't', overall: 61, scores: {} }) : null; };
  r = await S.call(U, 'coScore', { category: 'job', question: 'Q', audio: 'A'.repeat(2000) }); ok('retired model name: switches to the newest Flash by itself', r.ok && r.result.overall === 61, r);
  S.reply = null;
  S = await makeSim(translatorMod); await S.setSettings({ testMode: false }); await S.eng._setSecret(S.E, 'GEMINI_KEY', 'k');
  S.reply = (url) => (/generativelanguage/.test(url) ? { candidates: [{ content: { parts: [{ text: '```json\n' + JSON.stringify({ source_language: 'Somali', title: 'Birth Certificate', fields: [{ label: 'Name', value: 'Amina' }], body: '', labels: {} }) + '\n```' }] } }] } : null);
  r = await S.call(U, 'trTranslate', { doc: 'birth', to: 'en', pages: [{ data: 'AAAA', mime: 'image/jpeg' }] }); ok('translated (code-fenced JSON ok) + delivery token', r.ok && r.result.fields[0].value === 'Amina' && r.token, r);
  ok('second document blocked (1 free)', (await S.call(U, 'trTranslate', { doc: 'birth', to: 'en', pages: [{ data: 'AAAA' }] })).allowed === false);
  ok('history: no images stored', (await S.call(U, 'trHistory')).items[0].title === 'Birth Certificate' && !JSON.stringify(S.rows('Translations')).includes('AAAA'));
  S.reply = null;
}

section('Scholarship Finder on D1');
{
  const S = await makeSim(scholarMod); await S.setSettings({ testMode: false });
  for (const [i, n] of ['A', 'B', 'C', 'D', 'E'].entries()) await S.call(ADMIN, 'adminSchSave', { item: { name: 'Award ' + n, url: 'https://x.org', deadline: '2027-0' + (i + 1) + '-01', levels: ['master'], fields: ['any'], eligible: i === 4 ? ['SOUTH_ASIA'] : ['AFRICA'], funding: 'full' } });
  ok('non-admin cannot add', (await S.call(U, 'adminSchSave', { item: {} })).error === 'forbidden');
  ok('admin input checked', /required/.test((await S.call(ADMIN, 'adminSchSave', { item: { name: 'X', url: 'ftp://x', deadline: '2027-01-01' } })).error));
  ok('no profile yet: empty home', (await S.call(U, 'scHome')).profile === null);
  await S.call(U, 'scSaveProfile', { profile: { country: 'SO', level: 'master', field: 'agriculture', english: 'ielts', need: 'full', alerts: true } });
  await S.call(U, 'scSaveProfile', { profile: { country: 'SO', level: 'master', field: 'agriculture', english: 'ielts', need: 'full', alerts: true, gpa: '3.5' } });
  ok('profile saved once (second save updates)', S.rows('Profiles').length === 1 && S.rows('Profiles')[0].gpa === '3.5');
  r = await S.call(U, 'scHome'); ok('free: 3 shown, 1 locked (South Asia excluded)', r.matches.length === 3 && r.locked === 1 && r.profile.alerts === true && r.matches[0].score === 90, { n: r.matches.length, l: r.locked, p: r.profile, s: r.matches[0] });
  ok('earliest deadline first on equal score', r.matches[0].name === 'Award A' && r.matches[0].deadline === '2027-01-01');
  ok('save needs pro', (await S.call(U, 'scSave', { id: r.matches[0].id, on: true })).error === 'pro_required');
  await S.setSettings({ testMode: true });
  r = await S.call(U, 'scHome'); ok('pro: every match, nothing locked', r.matches.length === 4 && r.locked === 0);
  const first = r.matches[0].id; ok('save', (await S.call(U, 'scSave', { id: first, on: true })).saved.join() === first);
  ok('save twice = one row', (await S.call(U, 'scSave', { id: first, on: true })).saved.length === 1 && S.rows('Saved').length === 1);
  ok('saved list on home', (await S.call(U, 'scHome')).saved.join() === first);
  ok('unsave', (await S.call(U, 'scSave', { id: first, on: false })).saved.length === 0);
  const items = (await S.call(ADMIN, 'adminSchList')).items; ok('admin list', items.length === 5 && items[0].levels.join() === 'master');
  const b = items.find((x) => x.name === 'Award B'); await S.call(ADMIN, 'adminSchSave', { item: Object.assign({}, b, { status: 'hidden' }) });
  ok('hidden scholarship not matched', (await S.call(U, 'scHome')).matches.length === 3 && S.rows('Scholarships').length === 5);
  await S.call(ADMIN, 'adminSchDelete', { id: b.id }); ok('delete', S.rows('Scholarships').length === 4);
  const soon = new Date(Date.now() + 13 * 864e5).toISOString().slice(0, 10);   // 14 days left (counted to the end of the deadline day)
  await S.call(ADMIN, 'adminSchSave', { item: { name: 'Closing Soon', url: 'https://soon.org', deadline: soon, levels: ['master'], fields: ['any'], eligible: ['ALL'] } });
  await S.call(V, 'scSaveProfile', { profile: { country: 'SO', level: 'master', field: 'any', english: 'ielts', need: 'any', alerts: false } });
  let n0 = S.sent.length; await S.cron('daily'); const alerts = S.sent.slice(n0).filter((x) => /days left to apply/.test((x.payload || {}).text || ''));
  ok('deadline alert sent 14 days before, with the official website button', alerts.length === 1 && String(alerts[0].payload.chat_id) === '2002' && /^Closing Soon — 14 days left/.test(alerts[0].payload.text) && alerts[0].payload.reply_markup.inline_keyboard[0][0].url === 'https://soon.org', alerts.map((x) => x.payload));
  await S.setSettings({ testMode: false }); n0 = S.sent.length; await S.cron('daily');
  ok('no alert without Pro', !S.sent.slice(n0).some((x) => /days left to apply/.test((x.payload || {}).text || '')));
}

section('Field Tasks on D1: money, slots, photos');
{
  const S = await makeSim(marketMod); await S.setSettings({ testMode: false });
  r = await S.call(U, 'mkSaveTask', { task: { title: 'Shelf photo', instructions: 'Do it', city: 'Hargeisa', reward: 1, slots: 2, needs_photo: true, needs_gps: true, questions: ['Shop name'] } });
  ok('task total incl 20% fee', r.ok && r.task.total === 2.4 && r.task.status === 'awaiting_payment' && r.task.needs_photo === true && r.task.questions[0] === 'Shop name', r);
  const tid = r.task.id;
  ok('not in feed before payment', (await S.call(V, 'mkFeed', { city: 'hargeisa' })).tasks.length === 0);
  ok('bad task refused', (await S.call(U, 'mkSaveTask', { task: { title: 'x', instructions: 'y', city: 'z', reward: 0.1, slots: 1 } })).error === 'fields');
  await S.setSettings({ methods: { stars: true, usdt_trc20: '', usdt_bep20: '', evc: '', zaad: '', sahal: '', mpesa: '' } });
  ok('other user cannot pay my task', (await S.call(V, 'createOrder', { plan: 'task:' + tid, method: 'stars' })).ok === false);
  r = await S.call(U, 'createOrder', { plan: 'task:' + tid, method: 'stars' }); ok('task order (180 stars)', r.ok && S.rows('Payments')[0].amount === 180, r);
  await S.tg({ update_id: 11, pre_checkout_query: { id: 'pcm', from: { id: 2002 }, currency: 'XTR', total_amount: 180, invoice_payload: r.order_id } });
  ok('precheckout ok', S.sent.some((s) => s.method === 'answerPreCheckoutQuery' && s.payload.pre_checkout_query_id === 'pcm' && s.payload.ok === true));
  await S.tg(tgMsg(2002, { successful_payment: { invoice_payload: r.order_id, telegram_payment_charge_id: 'm1', total_amount: 180 } }));
  ok('paid: task live, owner told', S.rows('Tasks')[0].status === 'live' && S.sent.some((s) => /is now live/.test((s.payload || {}).text || '')));
  r = await S.call(V, 'mkFeed', { city: 'Hargeisa' }); ok('live in feed', r.tasks.length === 1 && r.tasks[0].id === tid, r);
  ok('worker city remembered', S.rows('Workers').some((w) => w.user_id === '3003' && w.city === 'Hargeisa'));
  ok('owner does not see own task', (await S.call(U, 'mkFeed', {})).tasks.length === 0);
  ok('owner cannot do own task', (await S.call(U, 'mkSubmit', { task: tid, photo: 'AAAA', lat: 1, lng: 2, answers: ['x'] })).error === 'own');
  ok('missing gps refused', (await S.call(V, 'mkSubmit', { task: tid, photo: 'AAAA', answers: ['x'] })).error === 'e_gps');
  ok('missing photo refused', (await S.call(V, 'mkSubmit', { task: tid, lat: 1, lng: 2, answers: ['x'] })).error === 'e_photo');
  ok('missing answer refused', (await S.call(V, 'mkSubmit', { task: tid, photo: 'AAAA', lat: 1, lng: 2, answers: [' '] })).error === 'e_answers');
  // Telegram keeps the photo (sent to the owner's chat); the database copy is removed
  const jpg = Buffer.from([0xff, 0xd8, 0xff, 0xe0, 1, 2, 3, 4, 0xff, 0xd9]);
  S.reply = (url) => (/\/sendPhoto$/.test(url) ? { ok: true, result: { photo: [{ file_id: 'small' }, { file_id: 'BIG' }] } } : /\/getFile$/.test(url) ? { ok: true, result: { file_path: 'photos/f1.jpg' } } : /\/file\/bot.*\/photos\/f1\.jpg$/.test(url) ? new Uint8Array(jpg) : null);
  ok('submit ok', (await S.call(V, 'mkSubmit', { task: tid, photo: jpg.toString('base64'), lat: 9.5, lng: 44, answers: ['Hodan'] })).ok);
  const sp = S.sent.find((s) => s.method === 'sendPhoto');
  ok('owner gets the photo in Telegram with an Open app button', sp && sp.raw === '[form]' && S.fetches.some((f) => /sendPhoto/.test(f.url) && f.o.body.get('chat_id') === '2002' && /New submission for "Shelf photo"/.test(f.o.body.get('caption'))));
  ok('photo kept by Telegram, not in the database', S.rows('Submissions')[0].photo_file === 'tg:BIG' && S.rows('Photos').length === 0, S.rows('Submissions')[0]);
  ok('duplicate refused', (await S.call(V, 'mkSubmit', { task: tid, photo: 'AAAA', lat: 9.5, lng: 44, answers: ['Hodan'] })).error === 'already');
  r = await S.call(U, 'mkSubs', { task: tid }); const link = r.subs[0].photo;
  ok('owner sees submission with a private photo link', r.subs.length === 1 && /^\/api\/file\?get=u\w+&exp=\d+&sig=\w{32}$/.test(link) && r.subs[0].answers[0] === 'Hodan' && r.subs[0].lat === 9.5, r);
  ok('the link stays the same all day (phone keeps the picture)', (await S.call(U, 'mkSubs', { task: tid })).subs[0].photo === link);
  let g = await S.get(link); ok('photo link shows the picture', g.status === 200 && g.type === 'image/jpeg' && Buffer.from(g.bytes).equals(jpg), g.status);
  ok('changed link refused', (await S.get(link.replace(/sig=\w/, 'sig=0'))).status === 404 && (await S.get(link.replace(/get=\w+/, 'get=u0'))).status === 404);
  ok('stranger cannot list submissions', (await S.call(V, 'mkSubs', { task: tid })).error === 'forbidden');
  // Telegram cannot deliver the photo: it stays in the database and is served from there
  const W2 = { id: 6006, first_name: 'Ayan' }; S.reply = (url) => (/\/sendPhoto$/.test(url) ? { ok: false, error_code: 403, description: 'Forbidden: bot was blocked by the user' } : null);
  ok('second worker takes the last slot', (await S.call(W2, 'mkSubmit', { task: tid, photo: jpg.toString('base64'), lat: 9.5, lng: 44, answers: ['Ayan shop'] })).ok);
  ok('photo kept in the database when Telegram refuses', S.rows('Submissions').find((s) => s.worker_id === '6006').photo_file === 'd1' && S.rows('Photos').length === 1);
  g = await S.get((await S.call(U, 'mkSubs', { task: tid })).subs[0].photo); ok('database photo served', g.status === 200 && Buffer.from(g.bytes).equals(jpg));
  S.reply = null;
  ok('task full: third worker refused', (await S.call({ id: 8008, first_name: 'Z' }, 'mkSubmit', { task: tid, photo: 'AAAA', lat: 1, lng: 1, answers: ['z'] })).error === 'full');
  ok('full task leaves the feed', (await S.call({ id: 8008, first_name: 'Z' }, 'mkFeed', { city: 'Hargeisa' })).tasks.length === 0);
  ok('owner sees 2 waiting', (await S.call(U, 'mkMine')).tasks[0].pending === 2);
  r = await S.call(U, 'mkSubs', { task: tid }); const subV = r.subs.find((x) => x.answers[0] === 'Hodan').id, subW = r.subs.find((x) => x.answers[0] === 'Ayan shop').id;
  ok('stranger cannot approve', (await S.call(V, 'mkDecide', { sub: subV, approve: true })).error === 'forbidden');
  const [a1, a2] = await Promise.all([S.call(U, 'mkDecide', { sub: subV, approve: true }), S.call(U, 'mkDecide', { sub: subV, approve: true })]);
  ok('approve twice at once: paid once', [a1, a2].filter((x) => x.ok).length === 1 && (await S.call(V, 'mkWallet')).balance === 1, [a1, a2]);
  ok('worker told', S.sent.some((s) => /Approved: "Shelf photo"\. \$1\.00/.test((s.payload || {}).text || '')));
  ok('reject with reason', (await S.call(U, 'mkDecide', { sub: subW, approve: false, reason: 'Blurry' })).ok && (await S.call(W2, 'mkWallet')).subs[0].reason === 'Blurry');
  ok('decided submission cannot change', (await S.call(U, 'mkDecide', { sub: subW, approve: true })).error === 'state');
  r = await S.call(V, 'mkWallet'); ok('wallet: balance, earned, my work with task title', r.balance === 1 && r.earned === 1 && r.subs[0].title === 'Shelf photo' && r.subs[0].status === 'approved', r);
  ok('withdraw: bad address', (await S.call(V, 'mkWithdraw', { address: 'xyz' })).error === 'address');
  ok('withdraw below min refused', (await S.call(V, 'mkWithdraw', { address: 'T' + 'A'.repeat(33) })).error === 'min');
  S.env.DB._db.prepare("UPDATE Workers SET balance = 6 WHERE user_id = '3003'").run();
  const [w1, w2] = await Promise.all([S.call(V, 'mkWithdraw', { address: 'T' + 'A'.repeat(33) }), S.call(V, 'mkWithdraw', { address: 'T' + 'A'.repeat(33) })]);
  ok('withdraw twice at once: one request', [w1, w2].filter((x) => x.ok).length === 1 && S.rows('Withdrawals').length === 1 && (await S.call(V, 'mkWallet')).balance === 0, [w1, w2]);
  ok('admin told about the request', S.sent.some((s) => /Withdrawal request: \$6\.00/.test((s.payload || {}).text || '')));
  r = await S.call(ADMIN, 'adminMk'); ok('admin sees withdrawal', r.withdrawals.length === 1 && r.withdrawals[0].amount === 6, r);
  ok('non-admin cannot see withdrawals', (await S.call(V, 'adminMk')).error === 'forbidden');
  ok('reject: money back to balance', (await S.call(ADMIN, 'adminMkWithdrawal', { id: r.withdrawals[0].id, paid: false })).ok && (await S.call(V, 'mkWallet')).balance === 6);
  ok('rejected once only', (await S.call(ADMIN, 'adminMkWithdrawal', { id: r.withdrawals[0].id, paid: false })).error === 'state' && (await S.call(V, 'mkWallet')).balance === 6);
  await S.call(V, 'mkWithdraw', { address: 'T' + 'B'.repeat(33) }); r = await S.call(ADMIN, 'adminMk');
  ok('mark paid', (await S.call(ADMIN, 'adminMkWithdrawal', { id: r.withdrawals[0].id, paid: true })).ok && S.sent.some((s) => /withdrawal of \$6\.00 has been sent/.test((s.payload || {}).text || '')));
  ok('wallet history', (await S.call(V, 'mkWallet')).withdrawals.map((x) => x.status).join() === 'paid,rejected');
  ok('photos not in the nightly backup', (await S.export('Photos')).error === 'table' && (await S.export('Submissions')).rows.length === 2);
  await S.setSettings({ testMode: true }); ok('test mode: task live at once', (await S.call(U, 'mkSaveTask', { task: { title: 'T', instructions: 'I', city: 'Burao', reward: 1, slots: 1 } })).task.status === 'live');
}

section('Channel Pass on D1');
{
  const S = await makeSim(gatekeeperMod); await S.setSettings({ testMode: true });
  const botAdmin = (status, inv = true, ban = true) => ({ update_id: Math.floor(Math.random() * 1e9), my_chat_member: { chat: { id: -100555, title: 'VIP Signals', type: 'channel' }, from: { id: 2002 }, new_chat_member: { status, can_invite_users: inv, can_restrict_members: ban } } });
  const joinReq = (uid) => ({ update_id: Math.floor(Math.random() * 1e9), chat_join_request: { chat: { id: -100555, title: 'VIP Signals' }, from: { id: uid }, user_chat_id: uid } });
  await S.tg(botAdmin('administrator', true, false));
  ok('missing rights: owner told what to fix', S.sent.some((s) => /Almost done/.test((s.payload || {}).text || '')) && S.rows('Channels')[0].bot_ok === 0);
  await S.tg(botAdmin('administrator'));
  r = await S.call(U, 'gkMine'); ok('channel registered to owner, with a join-request link', r.channels.length === 1 && r.channels[0].botOk && S.rows('Channels').length === 1 && S.rows('Channels')[0].invite_link === 'https://t.me/+abc', r);
  const key = r.channels[0].key;
  ok('owner saves plans', (await S.call(U, 'gkSave', { key, description: 'd', status: 'active', plans: [{ id: 'p1', label: '1 month', days: 30, usd: 5, stars: 350 }, { label: '' }] })).ok);
  ok('other user cannot edit', (await S.call(V, 'gkSave', { key, plans: [] })).error === 'forbidden');
  r = await S.call(V, 'gkChannel', { key }); ok('buyer sees offer', r.ok && r.channel.plans.length === 1 && !r.member && r.inviteLink === '', r);
  let n0 = S.sent.length; await S.tg(joinReq(3003));
  ok('join request before paying: plans offered, not approved', !S.sent.slice(n0).some((s) => s.method === 'approveChatJoinRequest') && S.sent.slice(n0).some((s) => /paid channel/.test((s.payload || {}).text || '') && /\?c=/.test(JSON.stringify(s.payload.reply_markup))));
  await S.setSettings({ testMode: false });
  r = await S.call(V, 'createOrder', { plan: key + '|p1', method: 'stars' }); ok('channel order 350 stars', r.ok && S.rows('Payments').find((p) => p.order_id === r.order_id).amount === 350, r);
  const o1 = r.order_id;
  await S.call(U, 'gkSave', { key, description: 'd', status: 'paused', plans: [{ id: 'p1', label: '1 month', days: 30, usd: 5, stars: 350 }] });
  ok('paused channel: no new orders', (await S.call(V, 'createOrder', { plan: key + '|p1', method: 'stars' })).error === 'plan');
  await S.tg({ update_id: 21, pre_checkout_query: { id: 'pcg', from: { id: 3003 }, currency: 'XTR', total_amount: 350, invoice_payload: o1 } });
  await S.tg(tgMsg(3003, { successful_payment: { invoice_payload: o1, telegram_payment_charge_id: 'g1', total_amount: 350 } }));
  r = await S.call(V, 'gkChannel', { key }); ok('member after pay (30 days, even though sales were paused meanwhile)', !!r.member && r.inviteLink === 'https://t.me/+abc' && Math.round((new Date(r.member.expiry) - Date.now()) / 864e5) === 30, r);
  ok('buyer gets join button, owner told', S.sent.some((s) => s.method === 'sendMessage' && String(s.payload.chat_id) === '3003' && /Tap below to join/.test(s.payload.text)) && S.sent.some((s) => /New subscriber in VIP Signals/.test((s.payload || {}).text || '')));
  await S.call(U, 'gkSave', { key, description: 'd', status: 'active', plans: [{ id: 'p1', label: '1 month', days: 30, usd: 5, stars: 350 }] });
  n0 = S.sent.length; await S.tg(joinReq(3003)); ok('join request approved', S.sent.slice(n0).some((s) => s.method === 'approveChatJoinRequest' && s.payload.user_id === 3003));
  ok('my subscriptions', (await S.call(V, 'gkMySubs')).subs[0].title === 'VIP Signals');
  r = await S.call(U, 'gkMembers', { key }); ok('owner sees member list', r.ok && r.members.length === 1 && r.members[0].name === 'Abdi' && r.members[0].status === 'active', r);
  ok('stranger cannot list members', (await S.call(V, 'gkMembers', { key })).error === 'forbidden');
  r = await S.call(U, 'gkMine'); ok('owner numbers: 1 member, 350 stars', r.channels[0].members === 1 && r.channels[0].revenue.stars === 350 && r.channels[0].revenue.orders === 1, r.channels[0]);
  ok('notify member', (await S.call(U, 'gkMemberAction', { key, user_id: 3003, op: 'notify', text: 'New signals at 9pm' })).ok && S.sent.some((s) => /New signals/.test((s.payload || {}).text || '')));
  r = await S.call(U, 'gkMemberAction', { key, user_id: 3003, op: 'extend', days: 7 }); ok('extend 7 days', r.ok && (new Date(r.expiry) - Date.now()) / 864e5 > 36 && S.rows('Members').length === 1, r);
  ok('extend a stranger refused', (await S.call(U, 'gkMemberAction', { key, user_id: 9999, op: 'extend', days: 7 })).error === 'not_member');
  r = await S.call(U, 'gkBroadcast', { key, text: 'Live session tonight' }); ok('broadcast queued', r.ok && r.queued === 1, r);
  ok('expiring-only broadcast skips long members', (await S.call(U, 'gkBroadcast', { key, text: 'x', audience: 'expiring' })).queued === 0);
  await S.cron('5min'); ok('outbox delivers', S.sent.some((s) => /Live session tonight/.test((s.payload || {}).text || '')));
  const banned0 = S.sent.filter((s) => s.method === 'banChatMember').length;
  ok('stop member', (await S.call(U, 'gkMemberAction', { key, user_id: 3003, op: 'stop', reason: 'test' })).ok && S.sent.filter((s) => s.method === 'banChatMember').length === banned0 + 1 && S.sent.some((s) => s.method === 'unbanChatMember'));
  r = await S.call(U, 'gkMembers', { key }); ok('member shows stopped', r.members[0].status === 'stopped', r.members);
  n0 = S.sent.length; await S.tg(joinReq(3003)); ok('stopped member not approved', !S.sent.slice(n0).some((s) => s.method === 'approveChatJoinRequest'));
  await S.call(U, 'gkMemberAction', { key, user_id: 3003, op: 'extend', days: 30 });
  ok('gift after stop: new active row', (await S.call(V, 'gkChannel', { key })).member.plan === 'gift');
  ok('creator code', (await S.call(U, 'gkCodeSave', { key, code: 'VIP20', pct: 20 })).ok && (await S.call(U, 'gkCodes', { key })).codes[0].code === 'VIP20');
  ok('stranger cannot make channel code', (await S.call(V, 'gkCodeSave', { key, code: 'HACK', pct: 90 })).error === 'forbidden');
  ok('creator code valid on channel plan', (await S.call(V, 'checkCode', { code: 'VIP20', plan: key + '|p1' })).pct === 20);
  await S.call(ADMIN, 'adminCodeSave', { code: 'PLAT50', pct: 50 });
  ok('platform code NOT valid on creator channel', (await S.call(V, 'checkCode', { code: 'PLAT50', plan: key + '|p1' })).error === 'code_not_for_plan');
  r = await S.call(V, 'createOrder', { plan: key + '|p1', method: 'stars', code: 'VIP20' }); ok('channel order with code: 280 stars', S.rows('Payments').some((x) => x.order_id === r.order_id && x.amount === 280), r);
  ok('code switched off', (await S.call(U, 'gkCodeToggle', { key, code: 'VIP20', active: false })).ok && (await S.call(V, 'checkCode', { code: 'VIP20', plan: key + '|p1' })).error === 'code_invalid');
  r = await S.call(ADMIN, 'adminGk'); ok('payout owed 95% of 350 stars', r.channels[0].owedStars === 332 && r.channels[0].members === 1, r);
  ok('owner cannot see platform payouts', (await S.call(U, 'adminGk')).error === 'forbidden');
  ok('platform fee changed', (await S.call(ADMIN, 'adminGkFee', { fee: 10 })).ok && (await S.call(ADMIN, 'adminGk')).channels[0].owedStars === 315);
  await S.eng._syncCentral(S.E, false); const today = new Date().toISOString().slice(0, 10);
  ok('central numbers count paying members as subscriptions', S.crows('Stats').find((x) => x.app === 'gatekeeper' && x.date === today).subs_active === 1, S.crows('Stats'));
  // reminders 2 days before, removal when the time is over
  S.env.DB._db.prepare("UPDATE Members SET expiry_date = ? WHERE status = 'active'").run(new Date(Date.now() + 864e5).toISOString());
  await S.cron('hourly'); await S.cron('5min'); ok('reminder 2 days before', S.sent.some((s) => /ends on/.test((s.payload || {}).text || '')) && S.rows('Members').find((m) => m.status === 'active').reminded === 'yes');
  n0 = S.sent.filter((s) => /ends on/.test((s.payload || {}).text || '')).length; await S.cron('hourly'); await S.cron('5min');
  ok('reminded once only', S.sent.filter((s) => /ends on/.test((s.payload || {}).text || '')).length === n0);
  S.env.DB._db.prepare("UPDATE Members SET expiry_date = ? WHERE status = 'active'").run(new Date(Date.now() - 1000).toISOString());
  const b0 = S.sent.filter((s) => s.method === 'banChatMember').length; await S.cron('hourly'); await S.cron('5min');
  ok('expired member removed and told how to renew', S.sent.filter((s) => s.method === 'banChatMember').length === b0 + 1 && (await S.call(V, 'gkChannel', { key })).member === null && S.sent.some((s) => /has ended/.test((s.payload || {}).text || '') && /Renew/.test(JSON.stringify(s.payload.reply_markup))));
  await S.tg(botAdmin('left')); ok('bot removed: channel marked removed', S.rows('Channels')[0].status === 'removed' && (await S.call(U, 'gkMine')).channels.length === 0);
  await S.tg(botAdmin('administrator')); ok('bot added again: paused, same channel', S.rows('Channels').length === 1 && S.rows('Channels')[0].status === 'paused');
}

section('migration from the real Apps Script (Debt Book)');
{
  const { createRequire } = await import('node:module'); const require = createRequire(import.meta.url); const { makeEnv } = require('./gas-sim.js');
  const G = makeEnv('debt'); G.setSettings({ testMode: false, freeAllowance: 5 }); G.props.WEBHOOK_SECRET_debt = WHSEC; G.props.GEMINI_KEY = 'gk';
  G.call(U, 'dbSaveShop', { shop: { name: 'Old Shop', currency: 'USD', freq: 'weekly', lang: 'en' } });
  const c1 = G.call(U, 'dbSaveCustomer', { name: 'Faarax', phone: '+252615550001' }).customer;
  G.call(U, 'dbAddEntry', { id: c1.id, type: 'debt', amount: 70, date: '2026-11-01', due: '2026-11-05' }); G.call(U, 'dbAddEntry', { id: c1.id, type: 'payment', amount: 20, method: 'cash' });
  G.call(U, 'dbAddEntry', { type: 'expense', amount: 9, category: 'Rent', method: 'cash' });
  G.call(U, 'ticketCreate', { type: 'question', text: 'How do reminders work?' });
  const posted = []; G.ctx.__fetchReply = (url, o) => { if (/\/api\/migrate$/.test(url) && !(o && o.method === 'post')) return { ok: true, backend: 'gas' }; if (/\/api\/migrate$/.test(url)) { posted.push({ body: o.payload, sig: o.headers['x-sig'] }); const b = JSON.parse(o.payload); return b.secrets ? { ok: true, secrets: Object.keys(b.secrets).length } : { ok: true }; } return { ok: true, result: {} }; };
  G.run('_rc = {}; migrateToCloudflare()'); G.ctx.__fetchReply = null;
  ok('Apps Script sent every tab + secrets, all signed', posted.length >= 8 && posted.every((p) => p.sig && p.sig.length === 64) && posted.some((p) => JSON.parse(p.body).secrets), posted.length);
  const T = await makeSim(debt);
  const replay = async () => { for (const p of posted) { const r = await T.eng.migrate({ request: { text: async () => p.body, headers: { get: (h) => (h === 'x-sig' ? p.sig : null) } }, env: T.env }); const j = await r.json(); if (!j.ok) return j; } return { ok: true }; };
  ok('Cloudflare accepted every signed part', (await replay()).ok);
  r = await T.call(U, 'dbBook');
  ok('same customers, balances and cashbook on D1', r.ok && r.shop.name === 'Old Shop' && r.customers.length === 1 && r.customers[0].balance === 50 && r.customers[0].phone === '+252615550001' && r.cash.length === 1 && r.cash[0].category === 'Rent', r);
  ok('free uses carried over', (await T.call(U, 'init')).access.freeUsed === 1);
  ok('support ticket carried to central', T.crows('Tickets').some((t) => t.app === 'debt' && t.user_id === '2002'));
  ok('Gemini key carried (encrypted)', T.rows('Secrets').some((x) => x.name === 'GEMINI_KEY') && !T.rows('Secrets').some((x) => x.val === 'gk'));
  G.ctx.__fetchReply = (url, o) => (/\/api\/migrate$/.test(url) ? (o && o.method === 'post' ? (posted.push({ late: true }), { ok: false, error: 'already_on_d1' }) : { ok: true, backend: 'd1' }) : { ok: true, result: {} });
  const n0 = posted.length; G.run('_rc = {}; migrateToCloudflare()');
  ok('after the switch, running the copy again sends nothing', posted.length === n0 && /already runs on Cloudflare/.test(G.logs.join('\n')) && !!G.props.MOVED_TO_D1, G.logs.slice(-2));
  G.props.LAST_CRON_HOURLY = 'before'; G.props.LAST_CRON_5MIN = 'before'; G.props.LAST_CRON_DAILY = 'before'; G.run('cronDaily(); cronHourly(); cronUsdt()');
  ok('Google timed jobs stop once Cloudflare serves the app', G.props.LAST_CRON_HOURLY === 'before' && G.props.LAST_CRON_5MIN === 'before' && G.props.LAST_CRON_DAILY === 'before');
  G.ctx.__fetchReply = null;
  await replay(); r = await T.call(U, 'dbBook');
  ok('running the copy again does not double anything', r.customers.length === 1 && r.customers[0].entries.length === 2 && T.crows('Tickets').filter((t) => t.app === 'debt').length === 1 && T.crows('TicketMsgs').length === 1, { n: r.customers.length, t: T.crows('Tickets').length, m: T.crows('TicketMsgs').length });
}

